alue?: Omit<Bookmark, \"id\" | \"created_at\" | \"updated_at\">; error?: string } {\n  const url = normalizeRequiredString(body.url);\n  if (!url) {\n    return { error: \"url is required\" };\n  }\n\n  if (!isValidUrl(url)) {\n    return { error: \"url must be a valid URL\" };\n  }\n\n  const title = normalizeRequiredString(body.title);\n  if (!title) {\n    return { error: \"title is required\" };\n  }\n\n  const folderId = normalizeOptionalFolderId(body.folder_id, userId);\n  if (folderId.error || folderId.value === undefined) {\n    return { error: folderId.error };\n  }\n\n  return {\n    value: {\n      url,\n      title,\n      description: normalizeDescription(body.description),\n      folder_id: folderId.value,\n    },\n  };\n}\n\napp.get(\"/health\", (_req, res) => {\n  res.status(200).json({ status: \"ok\" });\n});\n\napp.post(\"/auth/register\", (req, res) => {\n  const result = validateAuthBody(req.body as AuthBody);\n  if (result.error || !result.value) {\n    res.status(400).json({ error: result.error });\n    return;\n  }\n\n  const now = new Date().toISOString();\n  const passwordHash = bcrypt.hashSync(result.value.password, 10);\n\n  try {\n    const insertResult = createUser.run(result.value.email, passwordHash, now);\n    const user = getUserById.get(Number(insertResult.lastInsertRowid));\n    if (!user) {\n      res.status(500).json({ error: \"failed to create user\" });\n      return;\n    }\n\n    res.status(201).json(toPublicUser(user));\n  } catch (error) {\n    if (typeof error === \"object\" && error !== null && \"code\" in error && error.code === \"SQLITE_CONSTRAINT_UNIQUE\") {\n      res.status(409).json({ error: \"email already exists\" });\n      return;\n    }\n\n    throw error;\n  }\n});\n\napp.post(\"/auth/login\", (req, res) => {\n  const result = validateAuthBody(req.body as AuthBody);\n  if (result.error || !result.value) {\n    res.status(400).json({ error: result.error });\n    return;\n  }\n\n  const user = getUserByEmail.get