.url);\n  if (!url) {\n    res.status(400).json({ error: \"url is required\" });\n    return;\n  }\n\n  if (!isValidUrl(url)) {\n    res.status(400).json({ error: \"url must be a valid URL\" });\n    return;\n  }\n\n  const title = body.title === undefined ? existing.title : normalizeRequiredString(body.title);\n  if (!title) {\n    res.status(400).json({ error: \"title is required\" });\n    return;\n  }\n\n  const description = Object.prototype.hasOwnProperty.call(body, \"description\")\n    ? normalizeDescription(body.description)\n    : existing.description;\n  const folderId = Object.prototype.hasOwnProperty.call(body, \"folder_id\")\n    ? normalizeOptionalFolderId(body.folder_id, userId)\n    : { value: existing.folder_id };\n  if (folderId.error || folderId.value === undefined) {\n    res.status(400).json({ error: folderId.error });\n    return;\n  }\n  const now = new Date().toISOString();\n\n  updateBookmark.run(url, title, description, folderId.value, now, id, userId);\n\n  res.status(200).json(getBookmarkById.get(id, userId));\n});\n\napp.delete(\"/bookmarks/:id\", (req, res) => {\n  const userId = getAuthenticatedUserId(req);\n  const id = parseId(req.params.id);\n  if (!id) {\n    res.status(404).json({ error: \"bookmark not found\" });\n    return;\n  }\n\n  const result = deleteBookmark.run(id, userId);\n  if (result.changes === 0) {\n    res.status(404).json({ error: \"bookmark not found\" });\n    return;\n  }\n\n  res.status(204).send();\n});\n\napp.post(\"/folders\", (req, res) => {\n  const userId = getAuthenticatedUserId(req);\n  const name = normalizeRequiredString((req.body as FolderBody).name);\n  if (!name) {\n    res.status(400).json({ error: \"name is required\" });\n    return;\n  }\n\n  const now = new Date().toISOString();\n  const insertResult = createFolder.run(userId, name, now, now);\n  const folder = getFolderById.get(Number(insertResult.lastInsertRowid), userId);\n\n  res.status(201).json(folder);\n});\n\napp.get(\"/folders\", (req, res) => {\n  res.status(200).json(listFolders.all(getAuthenticatedUserId(req)));\n});\n\napp.get(\"/folders/:id\", (req, res) => {\n  const userId = getAuthenticatedUserId(req);\n  const id = parseId(req.params.id);\n  if (!id) {\n    res.status(404).json({ error: \"folder not found\" });\n    return;\n  }\n\n  const folder = getFolderById.get(id, userId);\n  if (!folder) {\n    res.status(404).json({ error: \"folder not found\" });\n    return;\n  }\n\n  res.status(200).json({\n    ...folder,\n    bookmarks: listBookmarksByFolderId.all(id, userId),\n  });\n});\n\napp.put(\"/folders/:id\", (req, res) => {\n  const userId = getAuthenticatedUserId(req);\n  const id = parseId(req.params.id);\n  if (!id) {\n    res.status(404).json({ error: \"folder not found\" });\n    return;\n  }\n\n  const existing = getFolderById.get(id, userId);\n  if (!existing) {\n    res.status(404).json({ error: \"folder not found\" });\n    return;\n  }\n\n  const name = normalizeRequiredString((req.body as FolderBody).name);\n  if (!name) {\n    res.status(400).json({ error: \"name is required\" });\n    return;\n  }\n\n  updateFolder.run(name, new Date().toISOString(), id, userId);\n\n  res.status(200).json(getFolderById.get(id, userId));\n});\n\napp.delete(\"/folders/:id\", (req, res) => {\n  const userId = getAuthenticatedUserId(req);\n  const id = parseId(req.params.id);\n  if (!id) {\n    res.status(404).json({ error: \"folder not found\" });\n    return;\n  }\n\n  const existing = getFolderById.get(id, userId);\n  if (!existing) {\n    res.status(404).json({ error: \"folder not found\" });\n    return;\n  }\n\n  const now = new Date().toISOString();\n  const removeFolder = db.transaction((folderId: number) => {\n    clearFolderBookmarks.run(now, folderId, userId);\n    deleteFolder.run(folderId, userId);\n  });\n  removeFolder(id);\n\n  res.status(204).send();\n});\n\napp.listen(PORT, () => {\n  console.log(`Server running on port ${PORT}`);\n});\n\nexport default app;\n","exit_cod