le = ?, description = ?, updated_at = ?\n+  WHERE id = ?\n+`);\n+\n+const deleteBookmark = db.prepare<[number]>(`\n+  DELETE FROM bookmarks\n+  WHERE id = ?\n+`);\n+\n+function parseId(id: string): number | null {\n+  const parsed = Number(id);\n+  return Number.isInteger(parsed) && parsed > 0 ? parsed : null;\n+}\n+\n+function normalizeRequiredString(value: unknown): string | null {\n+  return typeof value === \"string\" && value.trim().length > 0 ? value.trim() : null;\n+}\n+\n+function normalizeDescription(value: unknown): string | null {\n+  if (value === undefined || value === null) {\n+    return null;\n+  }\n+\n+  if (typeof value !== \"string\") {\n+    return null;\n+  }\n+\n+  const trimmed = value.trim();\n+  return trimmed.length > 0 ? trimmed : null;\n+}\n+\n+function isValidUrl(value: string): boolean {\n+  try {\n+    new URL(value);\n+    return true;\n+  } catch {\n+    return false;\n+  }\n+}\n+\n+function validateCreateBookmark(body: BookmarkBody): { value?: Omit<Bookmark, \"id\" | \"created_at\" | \"updated_at\">; error?: string } {\n+  const url = normalizeRequiredString(body.url);\n+  if (!url) {\n+    return { error: \"url is required\" };\n+  }\n+\n+  if (!isValidUrl(url)) {\n+    return { error: \"url must be a valid URL\" };\n+  }\n+\n+  const title = normalizeRequiredString(body.title);\n+  if (!title) {\n+    return { error: \"title is required\" };\n+  }\n+\n+  return {\n+    value: {\n+      url,\n+      title,\n+      description: normalizeDescription(body.description),\n+    },\n+  };\n+}\n+\n+app.get(\"/health\", (_req, res) => {\n+  res.status(200).json({ status: \"ok\" });\n+});\n+\n+app.post(\"/bookmarks\", (req, res) => {\n+  const result = validateCreateBookmark(req.body as BookmarkBody);\n+  if (result.error || !result.value) {\n+    res.status(400).json({ error: result.error });\n+    return;\n+  }\n+\n+  const now = new Date().toISOString();\n+  const insertResult = createBookmark.run(\n+    result.value.url,\n+    result.value.title,\n+    result.value.description,\n+    now,\n+    now,\n+  );\n+  const bookmark = getBookmarkById.get(Number(insertResult.lastInsertRowid));\n+\n+  res.status(201).json(bookmark);\n+});\n+\n+app.get(\"/bookmarks\", (_req, res) => {\n+  res.status(200).json(listBookmarks.all());\n+});\n+\n+app.get(\"/bookmarks/:id\", (req, res) => {\n+  const id = parseId(req.params.id);\n+  if (!id) {\n+    res.status(404).json({ error: \"bookmark not found\" });\n+    return;\n+  }\n+\n+  const bookmark = getBookmarkById.get(id);\n+  if (!bookmark) {\n+    res.status(404).json({ error: \"bookmark not found\" });\n+    return;\n+  }\n+\n+  res.status(200).json(bookmark);\n+});\n+\n+app.put(\"/bookmarks/:id\", (req, res) => {\n+  const id = parseId(req.params.id);\n+  if (!id) {\n+    res.status(404).json({ error: \"bookmark not found\" });\n+    return;\n+  }\n+\n+  const existing = getBookmarkById.get(id);\n+  if (!existing) {\n+    res.status(404).json({ error: \"bookmark not found\" });\n+    return;\n+  }\n+\n+  const body = req.body as BookmarkBody;\n+  const url = body.url === undefined ? existing.url : normalizeRequiredString(body.url);\n+  if (!url) {\n+    res.status(400).json({ error: \"url is required\" });\n+    return;\n+  }\n+\n+  if (!isValidUrl(url)) {\n+    res.status(400).json({ error: \"url must be a valid URL\" });\n+    return;\n+  }\n+\n+  const title = body.title === undefined ? existing.title : normalizeRequiredString(body.title);\n+  if (!title) {\n+    res.status(400).json({ error: \"title is required\" });\n+    return;\n+  }\n+\n+  const description = Object.prototype.hasOwnProperty.call(body, \"description\")\n+    ? normalizeDescription(body.description)\n+    : existing.description;\n+  const now = new Date().toISOString();\n+\n+  updateBookmark.run(url, title, description, now, id);\n+\n+  res.status(200).json(getBookmarkById.get(id));\n+});\n+\n+app.delete(\"/bookmarks/:id\", (req, res) => {\n+  const id = parseId(req.params.id);\n+  if (!id) {\n+    res.status(404).json({ error: \"bookmark not found\" });\n+    return;\n+  }\n+\n+  const result = deleteBookmark.run(id);\n+  if (result.changes === 0) {\n+    res.status(404).json({ error: \"bookmark not found\" });\n+    return;\n+  }\n+\n+  res.status(204).send();\n+});\n \n app.listen(PORT, () => {\n   console.log(`Server running on port ${PORT}`);\n","exit_code":0,"status":"completed"}}
