efined : findBookmark(id, userId);\n\n  if (!bookmark) {\n    res.status(404).json({ error: \"bookmark not found\" });\n    return;\n  }\n\n  res.status(200).json(bookmark);\n});\n\nrouter.put(\"/:id\", (req, res) => {\n  const userId = req.userId as number;\n  const id = parseId(req.params.id);\n  const existing = id === null ? undefined : findBookmark(id, userId);\n\n  if (!existing || id === null) {\n    res.status(404).json({ error: \"bookmark not found\" });\n    return;\n  }\n\n  const body = req.body as BookmarkBody;\n  let url = existing.url;\n  let title = existing.title;\n  let description = existing.description;\n  let folderId = existing.folder_id;\n\n  if (body.url !== undefined) {\n    if (!isNonEmptyString(body.url) || !isValidUrl(body.url.trim())) {\n      res.status(400).json({ error: \"url must be valid\" });\n      return;\n    }\n\n    url = body.url.trim();\n  }\n\n  if (body.title !== undefined) {\n    if (!isNonEmptyString(body.title)) {\n      res.status(400).json({ error: \"title must be non-empty\" });\n      return;\n    }\n\n    title = body.title.trim();\n  }\n\n  if (body.description !== undefined) {\n    description = typeof body.description === \"string\" ? body.description : null;\n  }\n\n  if (body.folder_id !== undefined) {\n    const parsedFolderId = parseFolderId(body.folder_id);\n\n    if (parsedFolderId === undefined) {\n      res\n        .status(400)\n        .json({ error: \"folder_id must reference an existing folder\" });\n      return;\n    }\n\n    if (\n      typeof parsedFolderId === \"number\" &&\n      !folderExists(parsedFolderId, userId)\n    ) {\n      res\n        .status(400)\n        .json({ error: \"folder_id must reference an existing folder\" });\n      return;\n    }\n\n    folderId = parsedFolderId;\n  }\n\n  const updatedAt = new Date().toISOString();\n\n  db.prepare(\n    `\n      UPDATE bookmarks\n      SET url = ?, title = ?, description = ?, folder_id = ?, updated_at = ?\n      WHERE id = ? AND user_i