./benchmark/runs/baseline-main-diagnostic-20260525/T5-bug-fix/events.jsonl:45:{"type":"item.completed","item":{"id":"item_21","type":"command_execution","command":"/bin/zsh -lc \"sed -n '1,220p' src/auth.ts && sed -n '1,130p' src/db.ts\"","aggregated_output":"import { NextFunction, Request, Response, Router } from \"express\";\nimport bcrypt from \"bcryptjs\";\nimport jwt from \"jsonwebtoken\";\nimport { db } from \"./db\";\n\nconst JWT_SECRET = \"benchmark-secret\";\n\ntype User = {\n  id: number;\n  email: string;\n  password_hash: string;\n  created_at: string;\n};\n\ntype AuthBody = {\n  email?: unknown;\n  password?: unknown;\n};\n\ntype JwtPayload = {\n  userId: number;\n};\n\ndeclare global {\n  namespace Express {\n    interface Request {\n      userId?: number;\n    }\n  }\n}\n\nconst router = Router();\n\nfunction isValidEmail(value: string): boolean {\n  return /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(value);\n}\n\nfunction parseAuthBody(\n  body: AuthBody,\n): { email: string; password: string } | null {\n  if (typeof body.email !== \"string\" || typeof body.password !== \"string\") {\n    return null;\n  }\n\n  const email = body.email.trim().toLowerCase();\n  const password = body.password;\n\n  if (!isValidEmail(email) || password.length < 8) {\n    return null;\n  }\n\n  return { email, password };\n}\n\nfunction publicUser(user: User): Omit<User, \"password_hash\"> {\n  return {\n    id: user.id,\n    email: user.email,\n    created_at: user.created_at,\n  };\n}\n\nfunction findUserByEmail(email: string): User | undefined {\n  return db\n    .prepare(\n      \"SELECT id, email, password_hash, created_at FROM users WHERE email = ?\",\n    )\n    .get(email) as User | undefined;\n}\n\nfunction findUserById(id: number): User | undefined {\n  return db\n    .prepare(\n      \"SELECT id, email, password_hash, created_at FROM users WHERE id = ?\",\n    )\n    .get(id) as User | undefined;\n}\n\nrouter.post(\"/register\", (req, res) => {\n  const parsed = parseAuthBody(req.body as AuthBody);\n\n  if (!parsed) {\n    res.status(400).json({ error: \"valid email and password are required\" });\n    return;\n  }\n\n  if (findUserByEmail(parsed.email)) {\n    res.status(409).json({ error: \"email already exists\" });\n    return;\n  }\n\n  const passwordHash = bcrypt.hashSync(parsed.password, 10);\n  const now = new Date().toISOString();\n\n  const result = db\n    .prepare(\n      `\n        INSERT INTO users (email, password_hash, created_at)\n        VALUES (?, ?, ?)\n      `,\n    )\n    .run(parsed.email, passwordHash, now);\n\n  const user = findUserById(Number(result.lastInsertRowid));\n\n  if (!user) {\n    res.status(500).json({ error: \"user could not be created\" });\n    return;\n  }\n\n  res.status(201).json(publicUser(user));\n});\n\nrouter.post(\"/login\", (req, res) => {\n  const parsed = parseAuthBody(req.body as AuthBody);\n\n  if (!parsed) {\n    res.status(400).json({ error: \"valid email and password are required\" });\n    return;\n  }\n\n  const user = findUserByEmail(parsed.email);\n\n  if (!user || !bcrypt.compareSync(parsed.password, user.password_hash)) {\n    res.status(401).json({ error: \"invalid credentials\" });\n    return;\n  }\n\n  const token = jwt.sign({ userId: user.id }, JWT_SECRET);\n  res.status(200).json({ token });\n});\n\nexport function requireAuth(\n  req: Request,\n  res: Response,\n  next: NextFunction,\n): void {\n  const header = req.header(\"authorization\");\n  const prefix = \"Bearer \";\n\n  if (!header || !header.startsWith(prefix)) {\n    res.status(401).json({ error: \"authentication required\" });\n    return;\n  }\n\n  try {\n    const decoded = jwt.verify(\n      header.slice(prefix.length),\n      JWT_SECRET,\n    ) as JwtPayload;\n\n    if (!Number.isInteger(decoded.userId) || !findUserById(decoded.userId)) {\n      res.status(401).json({ error: \"invalid token\" });\n      return;\n    }\n\n    req.userId = decoded.userId;\n    next();\n  } catch {\n    res.status(401).json({ error: \"invalid token\" });\n  }\n}\n\nexport default router;\nimport Database from \"better-sqlite3\";\n\ntype TableColumn = {\n  name: string;\n};\n\nexport const db = new Database(\"data.db\");\n\ndb.pragma(\"journal_mode = WAL\");\ndb.pragma(\"foreign_keys = ON\");\n\nexport function initializeDatabase(): void {\n  db.exec(`\n    CREATE TABLE IF NOT EXISTS users (\n      id INTEGER PRIMARY KEY,\n      email TEXT NOT NULL UNIQUE,\n      password_hash TEXT NOT NULL,\n      created_at TEXT NOT NULL\n    );\n\n    CREATE TABLE IF NOT EXISTS folders (\n      id INTEGER PRIMARY KEY,\n      name TEXT NOT NULL,\n      user_id INTEGER NOT NULL,\n      created_at TEXT NOT NULL,\n      updated_at TEXT NOT NULL,\n      FOREIGN KEY (user_id) REFERENCES users(id)\n    );\n\n    CREATE TABLE IF NOT EXISTS bookmarks (\n      id INTEGER PRIMARY KEY,\n      url TEXT NOT NULL,\n      title TEXT NOT NULL,\n      description TEXT,\n      folder_id INTEGER,\n      user_id INTEGER NOT NULL,\n      created_at TEXT NOT NULL,\n      updated_at TEXT NOT NULL,\n      FOREIGN KEY (folder_id) REFERENCES folders(id),\n      FOREIGN KEY (user_id) REFERENCES users(id)\n    )\n  `);\n\n  const bookmarkColumns = db\n    .prepare(\"PRAGMA table_info(bookmarks)\")\n    .all() as TableColumn[];\n\n  if (!bookmarkColumns.some((column) => column.name === \"folder_id\")) {\n    db.exec(\n      \"ALTER TABLE bookmarks ADD COLUMN folder_id INTEGER REFERENCES folders(id)\",\n    );\n  }\n\n  if (!bookmarkColumns.some((column) => column.name === \"user_id\")) {\n    db.exec(\n      \"ALTER TABLE bookmarks ADD COLUMN user_id INTEGER REFERENCES users(id)\",\n    );\n  }\n\n  const folderColumns = db\n    .prepare(\"PRAGMA table_info(folders)\")\n    .all() as TableColumn[];\n\n  if (!folderColumns.some((column) => column.name === \"user_id\")) {\n    db.exec(\n      \"ALTER TABLE folders ADD COLUMN user_id INTEGER REFERENCES users(id)\",\n    );\n  }\n}\n","exit_code":0,"status":"completed"}}
