erId as number;\n  const id = parseId(req.params.id);\n  const bookmark = id === null ? undefined : findBookmark(id, userId);\n\n  if (!bookmark) {\n    res.status(404).json({ error: \"bookmark not found\" });\n    return;\n  }\n\n  res.status(200).json(bookmark);\n});\n\nrouter.put(\"/:id\", (req, res) => {\n  const userId = req.userId as number;\n  const id = parseId(req.params.id);\n  const existing = id === null ? undefined : findBookmark(id, userId);\n\n  if (!existing || id === null) {\n    res.status(404).json({ error: \"bookmark not found\" });\n    return;\n  }\n\n  const body = getRequestBody(req.body) as BookmarkBody;\n  let url = existing.url;\n  let title = existing.title;\n  let description = existing.description;\n  let folderId = existing.folder_id;\n\n  if (body.url !== undefined) {\n    if (!isNonEmptyString(body.url) || !isValidUrl(body.url.trim())) {\n      res\n        .status(400)\n        .json({ error: \"url must be a non-empty valid URL\" });\n      return;\n    }\n\n    url = body.url.trim();\n  }\n\n  if (body.title !== undefined) {\n    if (!isNonEmptyString(body.title)) {\n      res.status(400).json({ error: \"title must be non-empty\" });\n      return;\n    }\n\n    title = body.title.trim();\n  }\n\n  if (body.description !== undefined) {\n    description = typeof body.description === \"string\" ? body.description : null;\n  }\n\n  if (body.folder_id !== undefined) {\n    const parsedFolderId = parseFolderId(body.folder_id);\n\n    if (parsedFolderId === undefined) {\n      res\n        .status(400)\n        .json({ error: \"folder_id must reference an existing folder\" });\n      return;\n    }\n\n    if (\n      typeof parsedFolderId === \"number\" &&\n      !folderExists(parsedFolderId, userId)\n    ) {\n      res\n        .status(400)\n        .json({ error: \"folder_id must reference an existing folder\" });\n      return;\n    }\n\n    folderId = parsedFolderId;\n  }\n\n  const updatedAt = new Date().toISOString();\n\n  db.prepare(\n    `\n      UPDATE bookmarks\n      SET url = ?, title = ?, description = ?, folder_id = ?, updated_at = ?\n      WHERE id = ? AND user_id = ?\n    `,\n  ).run(url, title, description, folderId, updatedAt, id, userId);\n\n  res.status(200).json(findBookmark(id, userId));\n});\n\nrouter.delete(\"/:id\", (req, res) => {\n  const userId = req.userId as number;\n  const id = parseId(req.params.id);\n  const result =\n    id === null\n      ? { changes: 0 }\n      : db\n          .prepare(\"DELETE FROM bookmarks WHERE id = ? AND user_id = ?\")\n          .run(id, userId);\n\n  if (result.changes === 0) {\n    res.status(404).json({ error: \"bookmark not found\" });\n    return;\n  }\n\n  res.status(204).send();\n});\n\nexport default router;\nimport { Router } from \"express\";\nimport { requireAuth } from \"./auth\";\nimport { db } from \"./db\";\nimport { getRequestBody, isNonEmptyString } from \"./validation\";\n\ntype Folder = {\n  id: number;\n  name: string;\n  created_at: string;\n  updated_at: string;\n};\n\ntype Bookmark = {\n  id: number;\n  url: string;\n  title: string;\n  description: string | null;\n  folder_id: number | null;\n  created_at: string;\n  updated_at: string;\n};\n\ntype FolderBody = {\n  name?: unknown;\n};\n\nconst router = Router();\n\nconst folderSelect = \"id, name, created_at, updated_at\";\nconst bookmarkSelect =\n  \"id, url, title, description, folder_id, created_at, updated_at\";\n\nrouter.use(requireAuth);\n\nfunction parseId(value: string): number | null {\n  const id = Number(value);\n  return Number.isInteger(id) && id > 0 ? id : null;\n}\n\nfunction findFolder(id: number, userId: number): Folder | undefined {\n  return db\n    .prepare(`SELECT ${folderSelect} FROM folders WHERE id = ? AND user_id = ?`)\n    .get(id, userId) as Folder | undefined;\n}\n\nrouter.post(\"/\", (req, res) => {\n  const userId = req.userId as number;\n  const body = getRequestBody(req.body) as FolderBody;\n\n  if (!isNonEmptyString(body.name)) {\n    res\n      .status(400)\n      .json({ error: \"name is required and must be non-empty\" });\n    return;\n  }\n\n  const now = new Date().toISOString();\n  const result = db\n    .prepare(\n      `\n        INSERT INTO folders (name, user_id, created_at, updated_at)\n        VALUES (?, ?, ?, ?)\n      `,\n    )\n    .run(body.name.trim(), userId, now, now);\n\n  res.status(201).json(findFolder(Number(result.lastInsertRowid), userId));\n});\n\nrouter.get(\"/\", (req, res) => {\n  const userId = req.userId as number;\n  const folders = db\n    .prepare(\n      `SELECT ${folderSelect} FROM folders WHERE user_id = ? ORDER BY id ASC`,\n    )\n    .all(userId) as Folder[];\n\n  res.status(200).json(folders);\n});\n\nrouter.get(\"/:id\", (req, res) => {\n  const userId = req.userId as number;\n  const id = parseId(req.params.id);\n  const folder = id === null ? undefined : findFolder(id, userId);\n\n  if (!folder || id === null) {\n    res.status(404).json({ error: \"folder not found\" });\n    return;\n  }\n\n  const bookmarks = db\n    .prepare(\n      `SELECT ${bookmarkSelect} FROM bookmarks WHERE folder_id = ? AND user_id = ? ORDER BY id ASC`,\n    )\n    .all(id, userId) as Bookmark[];\n\n  res.status(200).json({ ...folder, bookmarks });\n});\n\nrouter.put(\"/:id\", (req, res) => {\n  const userId = req.userId as number;\n  const id = parseId(req.params.id);\n  const existing = id === null ? undefined : findFolder(id, userId);\n\n  if (!existing || id === null) {\n    res.status(404).json({ error: \"folder not found\" });\n    return;\n  }\n\n  const body = getRequestBody(req.body) as FolderBody;\n\n  if (body.name !== undefined) {\n    if (!isNonEmptyString(body.name)) {\n      res.status(400).json({ error: \"name must be non-empty\" });\n      return;\n    }\n\n    db.prepare(\n      `\n        UPDATE folders\n        SET name = ?, updated_at = ?\n        WHERE id = ? AND user_id = ?\n      `,\n    ).run(body.name.trim(), new Date().toISOString(), id, userId);\n  }\n\n  res.status(200).json(findFolder(id, userId));\n});\n\nrouter.delete(\"/:id\", (req, res) => {\n  const userId = req.userId as number;\n  const id = parseId(req.params.id);\n  const existing = id === null ? undefined : findFolder(id, userId);\n\n  if (!existing || id === null) {\n    res.status(404).json({ error: \"folder not found\" });\n    return;\n  }\n\n  const deleteFolder = db.transaction((folderId: number, ownerId: number) => {\n    db.prepare(\n      \"UPDATE bookmarks SET folder_id = NULL, updated_at = ? WHERE folder_id = ? AND user_id = ?\",\n    ).run(new Date().toISOString(), folderId, ownerId);\n    db.prepare(\"DELETE FROM folders WHERE id = ? AND user_id = ?\").run(\n      folderId,\n      ownerId,\n    );\n  });\n\n  deleteFolder(id, userId);\n  res.status(204).send();\n});\n\nexport default router;\nexport function isNonEmptyString(value: unknown): value is string {\n  return typeof value === \"string\" && value.trim().length > 0;\n}\n\nexport function getRequestBody(value: unknown): Record<string, unknown> {\n  if (value !== null && typeof value === \"object\" && !Array.isArray(value)) {\n    return value as Record<string, unknown>;\n  }\n\n  return {};\n}\n","exit_code":0,"status":"completed"}}
