./benchmark/runs/baseline-main-valid-node22-20260525/T6-pagination/events.jsonl:29:{"type":"item.completed","item":{"id":"item_14","type":"command_execution","command":"/bin/zsh -lc \"sed -n '1,260p' src/folders.ts\"","aggregated_output":"import { Router } from \"express\";\nimport type { Request, Response } from \"express\";\nimport type Database from \"better-sqlite3\";\nimport { getAuthenticatedUserId } from \"./auth\";\n\ntype FolderRow = {\n  id: number;\n  user_id: number;\n  name: string;\n  created_at: string;\n  updated_at: string;\n};\n\ntype BookmarkRow = {\n  id: number;\n  user_id: number;\n  url: string;\n  title: string;\n  description: string | null;\n  folder_id: number | null;\n  created_at: string;\n  updated_at: string;\n};\n\ntype FolderResponse = Omit<FolderRow, \"user_id\">;\n\ntype FolderWithBookmarksResponse = FolderResponse & {\n  bookmarks: BookmarkResponse[];\n};\n\ntype BookmarkResponse = Omit<BookmarkRow, \"user_id\">;\n\nconst toFolderResponse = (row: FolderRow): FolderResponse => ({\n  id: row.id,\n  name: row.name,\n  created_at: row.created_at,\n  updated_at: row.updated_at,\n});\n\nconst toBookmarkResponse = (row: BookmarkRow): BookmarkResponse => ({\n  id: row.id,\n  url: row.url,\n  title: row.title,\n  description: row.description,\n  folder_id: row.folder_id,\n  created_at: row.created_at,\n  updated_at: row.updated_at,\n});\n\nconst readNonEmptyString = (value: unknown): string | undefined => {\n  if (typeof value !== \"string\") {\n    return undefined;\n  }\n\n  const trimmed = value.trim();\n  return trimmed.length > 0 ? trimmed : undefined;\n};\n\nconst getFolderId = (req: Request, res: Response): number | null => {\n  const id = Number(req.params.id);\n\n  if (!Number.isInteger(id) || id < 1) {\n    res.status(404).json({ error: \"Folder not found\" });\n    return null;\n  }\n\n  return id;\n};\n\nexport const createFoldersRouter = (db: Database.Database): Router => {\n  const router = Router();\n\n  const findById = db.prepare(\"SELECT * FROM folders WHERE id = ? AND user_id = ?\");\n  const findBookmarksByFolderId = db.prepare(\n    \"SELECT * FROM bookmarks WHERE folder_id = ? AND user_id = ? ORDER BY id ASC\",\n  );\n\n  router.post(\"/\", (req, res) => {\n    const userId = getAuthenticatedUserId(req);\n    const name = readNonEmptyString(req.body?.name);\n\n    if (!name) {\n      return res.status(400).json({ error: \"name must be a non-empty string\" });\n    }\n\n    const now = new Date().toISOString();\n    const result = db\n      .prepare(\n        `\n          INSERT INTO folders (user_id, name, created_at, updated_at)\n          VALUES (?, ?, ?, ?)\n        `,\n      )\n      .run(userId, name, now, now);\n\n    const folder = findById.get(result.lastInsertRowid, userId) as FolderRow;\n\n    return res.status(201).json(toFolderResponse(folder));\n  });\n\n  router.get(\"/\", (req, res) => {\n    const userId = getAuthenticatedUserId(req);\n    const folders = db\n      .prepare(\"SELECT * FROM folders WHERE user_id = ? ORDER BY id ASC\")\n      .all(userId) as FolderRow[];\n\n    return res.status(200).json(folders.map(toFolderResponse));\n  });\n\n  router.get(\"/:id\", (req, res) => {\n    const userId = getAuthenticatedUserId(req);\n    const id = getFolderId(req, res);\n    if (id === null) {\n      return;\n    }\n\n    const folder = findById.get(id, userId) as FolderRow | undefined;\n    if (!folder) {\n      return res.status(404).json({ error: \"Folder not found\" });\n    }\n\n    const bookmarks = findBookmarksByFolderId.all(id, userId) as BookmarkRow[];\n    const response: FolderWithBookmarksResponse = {\n      ...toFolderResponse(folder),\n      bookmarks: bookmarks.map(toBookmarkResponse),\n    };\n\n    return res.status(200).json(response);\n  });\n\n  router.put(\"/:id\", (req, res) => {\n    const userId = getAuthenticatedUserId(req);\n    const id = getFolderId(req, res);\n    if (id === null) {\n      return;\n    }\n\n    const existing = findById.get(id, userId) as FolderRow | undefined;\n    if (!existing) {\n      return res.status(404).json({ error: \"Folder not found\" });\n    }\n\n    const name =\n      req.body?.name === undefined ? existing.name : readNonEmptyString(req.body.name);\n    if (!name) {\n      return res.status(400).json({ error: \"name must be a non-empty string\" });\n    }\n\n    const updatedAt = new Date().toISOString();\n    db.prepare(\"UPDATE folders SET name = ?, updated_at = ? WHERE id = ? AND user_id = ?\").run(\n      name,\n      updatedAt,\n      id,\n      userId,\n    );\n\n    const updated = findById.get(id, userId) as FolderRow;\n\n    return res.status(200).json(toFolderResponse(updated));\n  });\n\n  router.delete(\"/:id\", (req, res) => {\n    const userId = getAuthenticatedUserId(req);\n    const id = getFolderId(req, res);\n    if (id === null) {\n      return;\n    }\n\n    const result = db.prepare(\"DELETE FROM folders WHERE id = ? AND user_id = ?\").run(\n      id,\n      userId,\n    );\n    if (result.changes === 0) {\n      return res.status(404).json({ error: \"Folder not found\" });\n    }\n\n    return res.status(204).send();\n  });\n\n  return router;\n};\n","exit_code":0,"status":"completed"}}
