n    56\t  return id;\n    57\t};\n    58\t\n    59\tconst readPaginationInteger = (\n    60\t  value: unknown,\n    61\t  defaultValue: number,\n    62\t): number | undefined => {\n    63\t  if (value === undefined) {\n    64\t    return defaultValue;\n    65\t  }\n    66\t\n    67\t  if (typeof value !== \"string\" || value.trim() === \"\") {\n    68\t    return undefined;\n    69\t  }\n    70\t\n    71\t  const parsed = Number(value);\n    72\t  return Number.isInteger(parsed) ? parsed : undefined;\n    73\t};\n    74\t\n    75\tconst readPagination = (\n    76\t  req: Request,\n    77\t  res: Response,\n    78\t): { page: number; limit: number } | null => {\n    79\t  const page = readPaginationInteger(req.query.page, 1);\n    80\t  const limit = readPaginationInteger(req.query.limit, 20);\n    81\t\n    82\t  if (page === undefined || page < 1) {\n    83\t    res.status(400).json({ error: \"page must be an integer greater than or equal to 1\" });\n    84\t    return null;\n    85\t  }\n    86\t\n    87\t  if (limit === undefined || limit < 1 || limit > 100) {\n    88\t    res.status(400).json({ error: \"limit must be an integer between 1 and 100\" });\n    89\t    return null;\n    90\t  }\n    91\t\n    92\t  return { page, limit };\n    93\t};\n    94\t\n    95\tconst readNonEmptyString = (value: unknown): string | undefined => {\n    96\t  if (typeof value !== \"string\") {\n    97\t    return undefined;\n    98\t  }\n    99\t\n   100\t  const trimmed = value.trim();\n   101\t  return trimmed.length > 0 ? trimmed : undefined;\n   102\t};\n   103\t\n   104\tconst readOptionalFolderId = (value: unknown): number | null | undefined => {\n   105\t  if (value === undefined || value === null) {\n   106\t    return null;\n   107\t  }\n   108\t\n   109\t  if (typeof value !== \"number\" || !Number.isInteger(value) || value < 1) {\n   110\t    return undefined;\n   111\t  }\n   112\t\n   113\t  return value;\n   114\t};\n   115\t\n   116\texport const createBookmarksRouter = (db: Database.Database): Router => {\n   117\t  const router = Router();\n   118\t\n   119\t  const findById = db.prepare(\"SELECT * FROM bookmarks WHERE id = ? AND user_id = ?\");\n   120\t  const findFolderById = db.prepare(\"SELECT id FROM folders WHERE id = ? AND user_id = ?\");\n   121\t  const countBookmarks = db.prepare(\n   122\t    \"SELECT COUNT(*) AS total FROM bookmarks WHERE user_id = ?\",\n   123\t  );\n   124\t  const findBookmarksPage = db.prepare(\n   125\t    \"SELECT * FROM bookmarks WHERE user_id = ? ORDER BY id ASC LIMIT ? OFFSET ?\",\n   126\t  );\n   127\t\n   128\t  const validateFolderId = (\n   129\t    value: unknown,\n   130\t    userId: number,\n   131\t    res: Response,\n   132\t  ): number | null | undefined => {\n   133\t    const folderId = readOptionalFolderId(value);\n   134\t\n   135\t    if (folderId === undefined) {\n   136\t      res.status(400).json({ error: \"folder_id must reference an existing folder\" });\n   137\t      return undefined;\n   138\t    }\n   139\t\n   140\t    if (folderId !== null && !findFolderById.get(folderId, userId)) {\n   141\t      res.status(400).json({ error: \"folder_id must reference an existing folder\" });\n   142\t      return undefined;\n   143\t    }\n   144\t\n   145\t    return folderId;\n   146\t  };\n   147\t\n   148\t  router.post(\"/\", (req, res) => {\n   149\t    const userId = getAuthenticatedUserId(req);\n   150\t    const url = readNonEmptyString(req.body?.url);\n   151\t    const title = readNonEmptyString(req.body?.title);\n   152\t    const description = req.body?.description;\n   153\t    const folderId = validateFolderId(req.body?.folder_id, userId, res);\n   154\t\n   155\t    if (folderId === undefined) {\n   156\t      return;\n   157\t    }\n   158\t\n   159\t    if (!url) {\n   160\t      return res.status(400).json({ error: \"url must be a non-empty string\" });\n   161\t    }\n   162\t\n   163\t    if (!title) {\n   164\t      return res.status(400).json({ error: \"title must be a non-empty string\" });\n   165\t    }\n   166\t\n   167\t    const now = new Date().toISOString();\n   168\t    const result = db\n   169\t      .prepare(\n   170\t        `\n   171\t          INSERT INTO bookmarks (user_id, url, title, description, folder_id, created_at, updated_at)\n   172\t          VALUES (?, ?, ?, ?, ?, ?, ?)\n   173\t        `,\n   174\t      )\n   175\t      .run(\n   176\t        userId,\n   177\t        url,\n   178\t        title,\n   179\t        typeof description === \"string\" ? description : null,\n   180\t        folderId,\n     1\t# US-006 Bookmark Pagination\n     2\t\n     3\t## Status\n     4\t\n     5\timplemented\n     6\t\n     7\t## Lane\n     8\t\n     9\tnormal\n    10\t\n    11\t## Product Contract\n    12\t\n    13\t`GET /bookmarks` returns a paginated JSON envelope scoped to the authenticated\n    14\tuser instead of a raw array.\n    15\t\n    16\t## Relevant Product Docs\n    17\t\n    18\t- `PRODUCT_SPEC.md`\n    19\t- `docs/stories/US-002-crud-bookmarks.md`\n    20\t- `docs/stories/US-004-authentication/overview.md`\n    21\t\n    22\t## Acceptance Criteria\n    23\t\n    24\t- `GET /bookmarks` returns `data`, `page`, `limit`, and `total`.\n    25\t- Default pagination uses `page=1` and `limit=20`.\n    26\t- `page` must be an integer greater than or equal to 1.\n    27\t- `limit` must be an integer from 1 through 100.\n    28\t- `total` counts all bookmarks for the authenticated user, not only returned\n    29\t  rows.\n    30\t- `GET /folders/:id` remains unpaginated.\n    31\t\n    32\t## Design Notes\n    33\t\n    34\t- Commands: none.\n    35\t- Queries: count authenticated user's bookmarks separately from the paginated\n    36\t  bookmark list query.\n    37\t- API: Express `GET /bookmarks` route accepts `page` and `limit` query params.\n    38\t- Tables: `bookmarks`.\n    39\t- Domain rules: pagination is user-scoped and ordered by bookmark id.\n    40\t- UI surfaces: none.\n    41\t\n    42\t## Validation\n    43\t\n    44\t| Layer | Expected proof |\n    45\t| --- | --- |\n    46\t| Unit | TypeScript build |\n    47\t| Integration | Manual HTTP smoke checks for default page, offset page, and invalid query params |\n    48\t| E2E | Existing authenticated bookmark CRUD flows still work |\n    49\t| Platform | Node/Express server starts on a local port |\n    50\t| Release | Not applicable |\n    51\t\n    52\t## Harness Delta\n    53\t\n    54\tNo harness changes expected.\n    55\t\n    56\t## Evidence\n    57\t\n    58\t- `npm run build` passed.\n    59\t- `npm test -- --passWithNoTests` passed with no test files present.\n    60\t- Manual HTTP smoke check passed for default pagination envelope,\n    61\t  `page=2&limit=5` offset, authenticated user-scoped `total`, invalid\n    62\t  `page`/`limit` values returning `400`, and unchanged `GET /folders` array\n    63\t  response.\n","exit_code":0,"status":"completed"}}
