function authenticate(req: Request, res: Response, next: NextFunction) {
  const authHeader = req.header("Authorization");
  if (!authHeader?.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.slice("Bearer ".length).trim();
  if (!token) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  try {
    const payload = jwt.verify(token, JWT_SECRET) as JwtPayload | string;
    if (typeof payload === "string" || typeof payload.userId !== "number") {
      return res.status(401).json({ error: "Unauthorized" });
    }

    const user = selectUserById.get(payload.userId) as User | undefined;
    if (!user) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    (req as AuthenticatedRequest).userId = payload.userId;
    next();
  } catch {
    return res.status(401).json({ error: "Unauthorized" });
  }
}

function validateFolderId(value: unknown, userId: number): string | null {
  if (value === null) {
    return null;
  }

  if (typeof value !== "number" || !Number.isInteger(value) || value <= 0) {
    return "folder_id must be a positive integer or null";
  }

  if (!getFolder(value, userId)) {
    return "folder_id does not reference an existing folder";
  }

  return null;
}

function parseTagIds(value: unknown, userId: number): number[] | string {
  if (!Array.isArray(value)) {
    return "tag_ids must be an array of positive integers";
  }

  const tagIds = [...new Set(value)];
  if (
    !tagIds.every(
      (tagId): tagId is number => typeof tagId === "number" && Number.isInteger(tagId) && tagId > 0,
    )
  ) {
    return "tag_ids must be an array of positive integers";
  }

  if (tagIds.length === 0) {
    return [];
  }

  const placeholders = tagIds.map(() => "?").join(", ");
  const { total } = db
    .prepare(`SELECT COUNT(*) AS total FROM tags WHERE user_id = ? AND id IN (${placeholders})`)
    .get(userId, ...tagIds) as CountRow;

  if (total !== tagIds.length) {
    return "tag_ids must reference existing tags owned by the current user";
  }

  return tagIds;
}

function setBookmarkTags(bookmarkId: number, tagIds: number[]) {
  db.prepare("DELETE FROM bookmark_tags WHERE bookmark_id = ?").run(bookmarkId);

